import { Stage } from "../Stage"

export default class extends Stage {
    protected *G(): Generator<void, void, unknown> {
        yield* this.wait(30)

        yield* this.text(`「ねえ。」`, { name: "シオン" })
        yield* this.text(`テルは装備の点検リストから目を上げなかった。`)
        yield* this.text(`「なんだよ。」`, { name: "テル" })
        yield* this.text(`「怖いって、思ったことある?」`, { name: "シオン" })
        yield* this.text(`「そりゃあるだろ、誰だって。」`, { name: "テル" })
        yield* this.text(`「そうじゃなくて。」`, { name: "シオン" })

        yield* this.text(`少女は言葉を探したが、うまく形にならなかった。`)
        yield* this.text(`「……もう、いい。」`, { name: "シオン" })
        yield* this.text(`「なんだよ、はっきり言え。」`, { name: "テル" })
        yield* this.text(`「言ったところで、分からないでしょ。」`, { name: "シオン" })

        yield* this.text(`テルは少しだけ手を止めたが、結局、リストに視線を戻した。`)
        yield* this.text(`「……悪いな。」`, { name: "テル" })
        yield* this.text(`それは謝罪の言葉のはずなのに、まるで他人事みたいに聞こえた。`)

        yield* this.text(`分かってほしい相手ほど、うまく言葉にできない。`)
        yield* this.text(`言葉にできたところで、多分、伝わらない。`)
    }
}
